/* @autogenerated */
package net.civeira.phylax.feature.observe.source;

import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceFilter;

/**
 * Saves every minute the last contact and the discarded events of each source (observed-source
 * last-seen-at and dropped-count), which the ingestion only keeps in memory. Only the sources that
 * changed are written, with the internal action record-activity (it does not reload the registry).
 */
@ApplicationScoped
@RequiredArgsConstructor
public class SourceActivityRecorder {

  private final SourceRegistry registry;
  private final ObservedSourceCommandRepositoryGateway sources;
  private final Map<String, String> saved = new ConcurrentHashMap<>();

  /** Called by the minute scheduler, outside any request. */
  public void record() {
    boolean activated = !Arc.container().requestContext().isActive();
    if (activated) {
      Arc.container().requestContext().activate();
    }
    try {
      Arc.container().instance(SourceActivityRecorder.class).get().save();
    } finally {
      if (activated) {
        Arc.container().requestContext().terminate();
      }
    }
  }

  @Transactional
  public void save() {
    for (SourceRegistry.Source source : registry.all()) {
      Long seen = registry.lastSeen(source.code()).orElse(null);
      if (null == seen) {
        continue;
      }
      long dropped = registry.dropped(source.code());
      String state = seen + ":" + dropped;
      if (state.equals(saved.get(source.uid()))) {
        continue;
      }
      sources.find(ObservedSourceFilter.builder().uid(source.uid()).build())
          .ifPresent(row -> sources.update(row,
              row.recordActivity(
                  OffsetDateTime.ofInstant(Instant.ofEpochMilli(seen), ZoneOffset.UTC),
                  (int) Math.min(Integer.MAX_VALUE, dropped))));
      saved.put(source.uid(), state);
    }
  }
}
